import{$ as e,A as t,B as n,V as r}from"./chunks/framework.qypF2UUz.js";var i=JSON.parse(`{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"docs/Glossary.md","filePath":"docs/Glossary.md"}`),a={name:`docs/Glossary.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to “Glossary”">​</a></h1><p>This glossary defines the terms used throughout the OWASP Application Gateway (OAG) documentation and configuration. Where a term maps directly to a configuration key or a value used in the configuration file, it is shown in <code>code font</code>.</p><h2 id="most-relevant-terms" tabindex="-1">Most relevant terms <a class="header-anchor" href="#most-relevant-terms" aria-label="Permalink to “Most relevant terms”">​</a></h2><p>These are the most important terms to understand first, and what they mean in the context of OAG.</p><table tabindex="0"><thead><tr><th>Term</th><th>Explanation</th></tr></thead><tbody><tr><td>Downstream System</td><td>Any system or application that is called (forwarded to) by OAG. Often services and applications implementing business logic.</td></tr><tr><td>Upstream System</td><td>Callers (initiating requests) of OAG. Often also known as clients.</td></tr><tr><td>Logging</td><td>Writing information about the inner workings (state) of OAG to a file or other destination.</td></tr><tr><td>Tracing</td><td>The goal of tracing is to follow a flow of activity and data processing (often known as request) through one or more systems/applications involved.</td></tr><tr><td>Log correlation / Correlation logging</td><td>The ability to assign log statements to a flow, effectively enabling tracing. Usually log correlation is implemented by assigning a unique id to each flow and writing this unique id out with every log statement.</td></tr></tbody></table><h2 id="all-terms" tabindex="-1">All terms <a class="header-anchor" href="#all-terms" aria-label="Permalink to “All terms”">​</a></h2><p>The following table lists all terms alphabetically.</p><table tabindex="0"><thead><tr><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td>Access token</td><td>The OAuth2 token OAG receives from the token endpoint after a successful login. OAG uses the login result to build the user&#39;s session; it is not forwarded to downstream systems as-is.</td></tr><tr><td><code>allowAnonymous</code></td><td>Per-route boolean. When <code>no</code>, OAG only forwards authenticated requests to the route; when <code>yes</code>, unauthenticated requests are allowed through.</td></tr><tr><td><code>allowedMethods</code></td><td>Per-security-profile list of permitted HTTP methods. Requests using a method not in the list are rejected with <code>405 Method Not Allowed</code>. Also called method whitelisting.</td></tr><tr><td>API key</td><td>A shared secret sent by OAG to a downstream system (for example via the <code>requestHeader</code> user mapping) so the backend can verify that a request originated from OAG.</td></tr><tr><td><code>apifornonebrowsers</code></td><td>Predefined security profile for APIs that are not called from a browser. Removes most browser-oriented security features of OAG.</td></tr><tr><td><code>apiforspa</code></td><td>Predefined security profile for an API called from a browser (single-page application). Adds CSRF protection using the double-submit-cookie pattern.</td></tr><tr><td>Authorization Code Flow</td><td>The OAuth2 / OpenID Connect flow OAG uses for login: the user is redirected to the authorization endpoint, returns with a code, and OAG exchanges the code for tokens at the token endpoint. Also called auth-code flow.</td></tr><tr><td>Authorization endpoint (<code>authEndpoint</code>)</td><td>The identity provider URL to which OAG redirects the user to begin authentication.</td></tr><tr><td>Authorization server</td><td>See Identity Provider (IdP).</td></tr><tr><td>Backend</td><td>See Downstream system.</td></tr><tr><td>Bean name</td><td>The Spring component name of a pluggable implementation. Configuration <code>type</code> values (trace, CSRF, key rotation, etc.) resolve to a bean by name, which is how custom code extensions are selected.</td></tr><tr><td>Claim</td><td>A key/value entry inside a JWT. OAG always sets <code>sub</code>, <code>aud</code>, <code>iat</code>, <code>nbf</code>, <code>exp</code>, <code>iss</code>, <code>jti</code>, and <code>provider</code>, and adds custom claims defined in the <code>mappings</code> section of the user mapping.</td></tr><tr><td>Client</td><td>See Upstream system.</td></tr><tr><td><code>clientId</code> / <code>clientSecret</code></td><td>The OAuth2 client credentials OAG presents to the identity provider. The secret is sensitive and is typically injected at runtime with the <code>env:</code> prefix.</td></tr><tr><td>Content Security Policy (CSP)</td><td>A response header (<code>Content-Security-Policy</code>) OAG can set through a security profile to restrict the sources a browser may load content from.</td></tr><tr><td>Cookie encryption (JWE)</td><td>OAG stores session data in cookies encrypted as JSON Web Encryption (JWE) using AES-256-GCM, so the client cannot read or tamper with the session.</td></tr><tr><td>Correlation ID</td><td>See Trace ID.</td></tr><tr><td>CSRF (Cross-Site Request Forgery)</td><td>An attack in which a victim&#39;s browser is tricked into sending an authenticated request. OAG mitigates it per security profile via the <code>csrfProtection</code> setting.</td></tr><tr><td><code>csrfProtection</code></td><td>Per-security-profile setting selecting the CSRF strategy: <code>double-submit-cookie</code>, <code>samesite-strict-cookie</code>, <code>none</code>, or a custom implementation.</td></tr><tr><td><code>csrfSafeMethods</code></td><td>Per-security-profile list of HTTP methods excluded from CSRF protection (typically <code>GET</code>, <code>HEAD</code>, <code>OPTIONS</code>).</td></tr><tr><td>Custom (code) extension</td><td>A pluggable Java component (e.g. implementing <code>CsrfProtectionValidation</code>, a trace context, a JWT signer, or a key store) that OAG selects by its bean name from configuration.</td></tr><tr><td><code>defaultKeyRotation</code></td><td>The built-in key rotation strategy. Generates a fresh signing key at startup, rotates it on the configured interval, and publishes keys to the JWK store.</td></tr><tr><td>Design principles</td><td>OAG&#39;s three guiding principles: secure by default (hardening out of the box), stateless (session state in encrypted client cookies), and configuration-based (behavior driven by one central config file).</td></tr><tr><td><code>double-submit-cookie</code></td><td>CSRF strategy where OAG requires the value of the <code>csrf</code> cookie to be echoed in the <code>X-CSRF-TOKEN</code> header (or a <code>CSRFToken</code> form field). OAG cryptographically binds the CSRF cookie to the session cookie.</td></tr><tr><td>Downstream system</td><td>Any service or application OAG forwards requests to — typically a backend implementing business logic. Also called downstream service or backend.</td></tr><tr><td><code>env:</code> prefix</td><td>Configuration value prefix that instructs OAG to read the value from an environment variable at runtime instead of storing it in the config file (used for secrets such as <code>clientSecret</code>).</td></tr><tr><td>Federated logout (<code>federatedLogoutUrl</code>)</td><td>Optional login-provider URL to which OAG redirects the user after logout so the session is also ended at the identity provider. When set, it overrides <code>redirectLogout</code>.</td></tr><tr><td><code>forwardIncomingTrace</code></td><td>Trace profile setting. When <code>false</code> (recommended at a trust boundary), OAG generates a new trace ID for every incoming request instead of reusing one supplied by an upstream system.</td></tr><tr><td>Gateway</td><td>See OAG.</td></tr><tr><td>GitHub provider (<code>github</code>)</td><td>Login provider type implementing GitHub&#39;s OAuth2 login. Requires at least the <code>user</code> and <code>email</code> scopes. GitHub does not implement OIDC, hence a dedicated driver.</td></tr><tr><td><code>hmac</code></td><td>JWT signer implementation producing HS256/HS384/HS512 signatures (chosen by key length) using a shared secret. Not recommended; adds a <code>kid</code> header but no <code>jku</code>.</td></tr><tr><td><code>hostUri</code></td><td>Top-level configuration value defining the public base URI under which OAG is reachable. Used, for example, as the default JWT <code>issuer</code>.</td></tr><tr><td>HSTS (<code>Strict-Transport-Security</code>)</td><td>HTTP Strict Transport Security response header OAG can set through a security profile to force browsers to use HTTPS.</td></tr><tr><td>HTTPS redirection</td><td>Built-in OAG feature that redirects HTTP requests to HTTPS while honoring proxy headers (proxy awareness).</td></tr><tr><td>ID token</td><td>The OpenID Connect token issued by the identity provider describing the authenticated user. OAG reads its claims into the user model for user mapping.</td></tr><tr><td>Identity Provider (IdP)</td><td>The external service that authenticates users and issues tokens (e.g. Google, Auth0, an internal OIDC server). Also called authorization server.</td></tr><tr><td>Issuer (<code>iss</code>)</td><td>JWT claim identifying who issued the token. For OAG-signed tokens it defaults to <code>&lt;&lt;hostUri&gt;&gt;</code>.</td></tr><tr><td><code>jku</code></td><td>JWT header carrying the URL of the JWK Set where the matching public key can be fetched. Added by the <code>rsa</code> JWT signer.</td></tr><tr><td>JWK (JSON Web Key)</td><td>A JSON representation of a cryptographic key. OAG publishes its RSA signing public keys as JWKs.</td></tr><tr><td>JWK store (<code>jwkStoreProfile</code>)</td><td>Component holding OAG&#39;s signing keys. The built-in <code>localRsaJwkStore</code> keeps valid keys (plus a grace period) in memory only.</td></tr><tr><td>JWKS / JWK Set</td><td>A set of JWKs. OAG exposes its current and historical signing public keys as a JWK Set (RFC 7517) at <code>/.well-known/jwks</code> (and <code>/.well-known/jwks/&lt;kid&gt;</code>).</td></tr><tr><td>JWS (JSON Web Signature)</td><td>The signature standard (RFC 7515) a downstream system verifies to confirm an OAG-issued JWT is authentic and unmodified.</td></tr><tr><td>JWT (JSON Web Token)</td><td>A signed token OAG can issue to convey user identity to downstream systems (the <code>jwtToken</code> user mapping). The backend validates the signature using OAG&#39;s published public key.</td></tr><tr><td>JWT signer (<code>signatureImplementation</code>)</td><td>The component that signs user-mapping JWTs. Supported values: <code>rsa</code> (RS256, recommended) and <code>hmac</code> (HS256/384/512, not recommended).</td></tr><tr><td>Key generator (<code>keyGeneratorProfile</code>)</td><td>Component that creates signing keys. The built-in <code>rsaKeyGenerator</code> produces RSA keys of the configured <code>keySize</code>.</td></tr><tr><td>Key management profile (<code>keyManagementProfile</code>)</td><td>Top-level configuration grouping the key rotation, JWK store, and key generator profiles that together manage OAG&#39;s signing keys.</td></tr><tr><td>Key rotation (<code>keyRotationProfile</code>)</td><td>Configuration controlling how often OAG generates a new signing key (<code>signingKeyRotationSeconds</code>) and cleans up expired keys (<code>cleanupFrequencySeconds</code>).</td></tr><tr><td><code>kid</code> (key ID)</td><td>Identifier of a specific signing key. Present in the JWT header and usable to fetch that key from the JWKS endpoint.</td></tr><tr><td><code>localRsaJwkStore</code></td><td>Built-in JWK store implementation that keeps RSA signing keys in memory locally for as long as they are valid (plus a grace period).</td></tr><tr><td>Log correlation / Correlation logging</td><td>Assigning log statements to a single flow by writing a shared trace ID with every log statement, which makes tracing across systems possible.</td></tr><tr><td>Logging</td><td>Writing information about OAG&#39;s internal state and activity to a file or other destination.</td></tr><tr><td>Login driver</td><td>The code component implementing a login provider. It builds the authorization redirect (returning the auth URI and <code>state</code>) and turns the provider&#39;s callback into a user model.</td></tr><tr><td>Login provider</td><td>A configured way for users to authenticate (<code>loginProviders</code> section). Each provider has a <code>type</code> (<code>oidc</code> or <code>github</code>) and provider-specific settings under <code>with</code>.</td></tr><tr><td>Method whitelisting</td><td>See <code>allowedMethods</code>.</td></tr><tr><td><code>no</code> (user mapping)</td><td>User mapping type that adds no user information to the forwarded request. Suitable for backends serving only public content.</td></tr><tr><td><code>noTraceContext</code></td><td>Trace implementation that disables tracing toward downstream and upstream systems, using a trace ID only for OAG&#39;s own logs. Not recommended.</td></tr><tr><td>OAG (OWASP Application Gateway)</td><td>An HTTP reverse proxy that sits between clients and web applications and handles OAuth2/OIDC login, session management, and the security tokens forwarded to backends.</td></tr><tr><td>OAuth2</td><td>The authorization framework OAG builds on for login. Both the <code>oidc</code> and <code>github</code> providers use OAuth2.</td></tr><tr><td>OIDC provider (<code>oidc</code>)</td><td>Login provider type for any identity provider implementing OpenID Connect. OAG uses the authorization code flow.</td></tr><tr><td>OpenID Connect (OIDC)</td><td>An identity layer on top of OAuth2 that OAG uses to authenticate users and obtain an ID token.</td></tr><tr><td>Path (<code>path</code>)</td><td>Per-route ant-style pattern deciding which incoming request paths the route handles (<code>/svc/</code>, <code>/svc/*</code>, <code>/svc/**</code>).</td></tr><tr><td>Persistent map</td><td>OAG&#39;s key/value storage abstraction (<code>PersistentMap</code>) with <code>FilePersistentMap</code> and <code>InMemoryPersistentMap</code> implementations. Backs, for example, the session blacklist.</td></tr><tr><td>Predefined profile</td><td>A security profile shipped with OAG: <code>static</code>, <code>webapplication</code>, <code>apiforspa</code>, <code>apifornonebrowsers</code>. Any can be overridden or supplemented in the config file.</td></tr><tr><td>Provider</td><td>See Login provider. Also the JWT/session <code>provider</code> value naming which login provider the user authenticated with.</td></tr><tr><td><code>redirectLoginFailure</code> / <code>redirectLoginSuccess</code> / <code>redirectLogout</code></td><td>Session-behaviour URLs OAG redirects the user to after a failed login, a successful login, and logout respectively.</td></tr><tr><td><code>renewWhenLessThan</code></td><td>Session-behaviour setting enabling a rolling session: if a still-valid session has less than this many seconds left, OAG issues a fresh session of full <code>sessionDuration</code>.</td></tr><tr><td><code>requestHeader</code> (user mapping)</td><td>User mapping type that conveys user identity as plain HTTP headers. Less secure than <code>jwtToken</code>; requires network isolation and typically a shared API key.</td></tr><tr><td>Response headers (<code>responseHeaders</code>)</td><td>Per-security-profile rules that add, overwrite (<code>value</code>), or remove (<code>&lt;&lt;remove&gt;&gt;</code>) headers on responses returned to the client.</td></tr><tr><td>Reverse proxy</td><td>A server that receives client requests and forwards them to backend servers, returning the backend&#39;s response. OAG is a reverse proxy.</td></tr><tr><td>Rewrite (<code>rewrite</code>)</td><td>Per-route rule controlling how the request path is transformed before being forwarded to the downstream URL. Defaults to stripping the matched path prefix; can be customized with <code>regex</code>/<code>replacement</code>.</td></tr><tr><td>Rolling session</td><td>A session that is automatically extended while the user stays active, controlled by <code>renewWhenLessThan</code>.</td></tr><tr><td>Route</td><td>A configuration entry (under <code>routes</code>) mapping an incoming <code>path</code> to a downstream <code>url</code>, using a named security profile (<code>type</code>) and an <code>allowAnonymous</code> policy.</td></tr><tr><td><code>rsa</code></td><td>Recommended JWT signer implementation. Produces RS256 signatures using automatically rotated keys and adds <code>kid</code> and <code>jku</code> headers.</td></tr><tr><td><code>rsaKeyGenerator</code></td><td>Built-in key generator that produces RSA keys of the configured <code>keySize</code>.</td></tr><tr><td><code>samesite-strict-cookie</code></td><td>CSRF strategy relying on a SameSite=Strict session cookie so the browser does not send it on cross-site requests.</td></tr><tr><td>Scopes (<code>scopes</code>)</td><td>The OAuth2/OIDC scopes OAG requests from the identity provider. <code>openid</code> is required for OIDC; others (e.g. <code>email</code>) are optional.</td></tr><tr><td>Security headers</td><td>The set of hardening HTTP response headers OAG sets by default through security profiles, such as <code>X-Frame-Options</code>, <code>X-Content-Type-Options</code>, <code>Content-Security-Policy</code>, <code>Referrer-Policy</code>, and <code>Permissions-Policy</code>.</td></tr><tr><td>Security profile</td><td>A named bundle of security settings — <code>allowedMethods</code>, <code>csrfProtection</code>, <code>responseHeaders</code>, <code>userMapping</code> — referenced by a route&#39;s <code>type</code> and applied to all its requests.</td></tr><tr><td>Security token</td><td>A token used to convey authenticated identity or authorization, such as an OAuth2 access token, an OIDC ID token, or an OAG-issued JWT.</td></tr><tr><td>Session</td><td>The authenticated state of a user with OAG. OAG is stateless: session data is stored in an encrypted cookie on the client.</td></tr><tr><td>Session blacklist</td><td>A store of invalidated session identifiers (for example after logout). An identifier stays blacklisted for at least its TTL so the session cannot be reused.</td></tr><tr><td>Session cookie</td><td>The secure, HTTP-only, SameSite cookie in which OAG stores encrypted session information on the client.</td></tr><tr><td><code>sessionBehaviour</code></td><td>Configuration section defining session handling: <code>sessionDuration</code>, <code>renewWhenLessThan</code>, and the post-login/logout redirect URLs.</td></tr><tr><td><code>sessionDuration</code></td><td>Number of seconds a session cookie is valid after authentication (default 3600).</td></tr><tr><td>Sign-in endpoint</td><td>The OAG URL a client calls to start login for a provider: <code>/auth/{login-provider-name}/login</code>.</td></tr><tr><td><code>simpleTraceContext</code></td><td>Trace implementation using a random UUID as the trace ID and, by default, the <code>X-Correlation-Id</code> header to propagate it.</td></tr><tr><td>Single-page application (SPA)</td><td>A browser front-end served as static files that calls APIs. The <code>static</code> and <code>apiforspa</code> profiles target this case.</td></tr><tr><td><code>state</code></td><td>The OAuth2 state parameter OAG generates during login and validates on the callback to maintain state and protect the login flow.</td></tr><tr><td><code>static</code> (profile)</td><td>Predefined security profile for static content: default security headers and only <code>GET</code>, <code>HEAD</code>, <code>OPTIONS</code> allowed.</td></tr><tr><td>Stateless</td><td>A design principle of OAG: no server-side session storage, so it can run on multiple nodes without shared state. All session state lives in encrypted client cookies.</td></tr><tr><td>TLS configuration</td><td>Configuration of the certificate and TLS settings OAG serves over HTTPS. OAG ships a self-signed localhost certificate that is meant to be replaced for production.</td></tr><tr><td>Token endpoint (<code>tokenEndpoint</code>)</td><td>The identity provider URL from which OAG retrieves the access and ID tokens after the user is redirected back with an authorization code.</td></tr><tr><td>Trace ID</td><td>A unique identifier applied to each request reaching OAG and propagated to downstream (and optionally upstream) systems to enable tracing. Also called correlation ID. Available in logs as <code>oag.CorrId</code>.</td></tr><tr><td>Trace profile (<code>traceProfile</code>)</td><td>Configuration section controlling tracing behavior: implementation <code>type</code>, whether to forward/return trace info, and length limits.</td></tr><tr><td>Tracing</td><td>Following a single flow of activity and data as it passes through one or more systems, enabled by propagating a shared trace ID.</td></tr><tr><td>Trust boundary / trust zone</td><td>The edge of a trusted network area. OAG typically sits at the trust boundary, which is why it generates its own trace IDs rather than trusting upstream-supplied ones.</td></tr><tr><td><code>trustedRedirectHosts</code></td><td>Configured allowlist of hosts OAG is permitted to redirect to, guarding the login/logout <code>returnUrl</code> against open-redirect attacks.</td></tr><tr><td><code>type</code></td><td>Context-dependent selector: on a route it names the security profile; on a login provider it names the provider driver (<code>oidc</code>/<code>github</code>); in the key/trace profiles it names the implementation to use.</td></tr><tr><td>Upstream system</td><td>A caller that initiates requests to OAG — often a browser or client application.</td></tr><tr><td>URL (<code>url</code>)</td><td>Per-route downstream base URL to which matching requests are forwarded (after path rewriting).</td></tr><tr><td>User mapping (<code>userMapping</code>)</td><td>The security-profile section defining how OAG communicates the authenticated user to the backend. Types: <code>jwtToken</code> (recommended), <code>requestHeader</code>, <code>no</code>.</td></tr><tr><td>User model</td><td>The internal representation of the authenticated user, populated from the identity provider&#39;s ID token claims and referenced in mapping expressions as <code>mappings.*</code>.</td></tr><tr><td><code>w3cTraceContext</code></td><td>Default trace implementation, compliant with the W3C Trace Context specification, using its standard headers to propagate the trace ID.</td></tr><tr><td>W3C Trace Context</td><td>A W3C specification for propagating trace context via standard HTTP headers, implemented by OAG&#39;s default <code>w3cTraceContext</code>.</td></tr><tr><td><code>webapplication</code> (profile)</td><td>Predefined security profile suitable for most web applications: allows the common HTTP methods and adds SameSite-cookie CSRF protection.</td></tr><tr><td>Whitelisting (URLs)</td><td>The set of OAG URLs that must be reachable through a firewall or WAF, including the <code>/auth**</code> authentication endpoints, the configured routes, and the <code>/.well-known/jwks**</code> and <code>/oag/**</code> operational endpoints.</td></tr></tbody></table>`,8)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};